_V17_MD_FRACTION = 2.0
_V17_ROOM_GUARD = True
_V17_FEED_GUARD = False
_V17_MD_ITEMS = ("MELON", "MILK", "STRAWBERRY", "WOOL")
_V17_MD_STATE = {
    0: {"last_step": -1, "target": False},
    1: {"last_step": -1, "target": False},
}
_V17_FEED_RESCUE_STATE = {
    0: {"last_step": -1, "day": -1, "active": {}},
    1: {"last_step": -1, "day": -1, "active": {}},
}
_V17_ROOM_EVAC_STATE = {
    0: {"last_step": -1, "day": -1, "active": None},
    1: {"last_step": -1, "day": -1, "active": None},
}


def _v17_md_signature(obs):
    seat = _seat(obs)
    farms = list(_get(obs, "farms", []) or [])
    opponent = farms[1 - seat] if len(farms) >= 2 else {}
    cows = sheep = 0
    for row in list(_get(opponent, "tiles", []) or []):
        for tile in list(row or []):
            if not isinstance(tile, dict):
                continue
            cows += int(tile.get("animal") == "COW")
            sheep += int(tile.get("animal") == "SHEEP")
    quadrants = len(_get(opponent, "unlocked_quadrants", []) or [])
    return cows, sheep, quadrants


def _v17_is_md_family(obs, step):
    seat = _seat(obs)
    state = _V17_MD_STATE[seat]
    if step == 0 or step < int(state.get("last_step", -1)):
        state = {"last_step": step, "target": False}
        _V17_MD_STATE[seat] = state
    state["last_step"] = step
    if not state.get("target") and step >= 160:
        cows, sheep, quadrants = _v17_md_signature(obs)
        if (quadrants >= 2 and cows >= 4 and sheep <= 2) or cows >= 9:
            state["target"] = True
    return bool(state.get("target"))


def _v17_md_pickup_reserve(action, item):
    reserve = 0
    for order in [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]:
        if isinstance(order, (list, tuple)) and len(order) >= 2 and order[0] == "PICKUP" and order[1] == item:
            reserve += max(0, int(order[2])) if len(order) >= 3 else 1
    return reserve


def _v17_md_counter(obs, action, step):
    if _V17_MD_FRACTION <= 0 or not _v17_is_md_family(obs, step) or step + 1 >= len(_V17_MD_MARKETS):
        return action
    targets = {}
    for order in _V17_MD_MARKETS[step + 1]:
        if len(order) >= 3 and order[0] == "SELL" and order[1] in _V17_MD_ITEMS:
            targets[order[1]] = targets.get(order[1], 0) + max(0, int(order[2] or 0))
    if not targets:
        return action
    action = _copy_action(action)
    market = [list(order) for order in (action.get("market") or [])]
    shed = dict(_get(_get(obs, "private", {}) or {}, "shed", {}) or {})
    for item in _V17_MD_ITEMS:
        target = targets.get(item, 0)
        if target <= 0:
            continue
        existing_quantity = sum(
            max(0, int(order[2] or 0))
            for order in market
            if len(order) >= 3 and order[0] == "SELL" and order[1] == item
        )
        available = max(
            0,
            int(shed.get(item, 0) or 0)
            - existing_quantity
            - _v17_md_pickup_reserve(action, item),
        )
        quantity = min(available, max(1, int(round(target * _V17_MD_FRACTION))))
        if quantity <= 0:
            continue
        existing = next(
            (order for order in market if len(order) >= 3 and order[0] == "SELL" and order[1] == item),
            None,
        )
        if existing is not None:
            existing[2] = max(0, int(existing[2] or 0)) + quantity
        elif len(market) < 10:
            market.append(["SELL", item, quantity])
        else:
            continue
    action["market"] = market[:10]
    return action


def _v17_move_toward(position, target):
    x, y = int(position[0]), int(position[1])
    tx, ty = int(target[0]), int(target[1])
    if x < tx:
        return ["EAST"]
    if x > tx:
        return ["WEST"]
    if y < ty:
        return ["SOUTH"]
    if y > ty:
        return ["NORTH"]
    return ["PASS"]


def _v17_feed_guard(obs, action, step):
    hour = int(_get(obs, "hour", 0) or 0)
    day = int(_get(obs, "day", step // 24) or 0)
    if not _V17_FEED_GUARD or hour < 18:
        return action
    action = _align_hands(action, obs)
    seat = _seat(obs)
    state = _V17_FEED_RESCUE_STATE[seat]
    if step == 0 or step < int(state.get("last_step", -1)) or day != int(state.get("day", -1)):
        state = {"last_step": step, "day": day, "active": {}}
        _V17_FEED_RESCUE_STATE[seat] = state
    state["last_step"] = step
    farm = _farm(obs, seat)
    private = _get(obs, "private", {}) or {}
    positions = [_get(farm, "farmer", [4, 4]), *list(_get(farm, "hands", []) or [])]
    inventories = list(_get(private, "inventories", []) or [])
    orders = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]

    threats = []
    for y, row in enumerate(list(_get(farm, "tiles", []) or [])):
        for x, tile in enumerate(list(row or [])):
            if (
                isinstance(tile, dict)
                and tile.get("animal")
                and int(tile.get("consecutive_unfed", 0) or 0) >= 1
                and not tile.get("fed_today", False)
            ):
                threats.append((x, y))
    threat_set = set(threats)
    active = state.setdefault("active", {})
    for actor, target in list(active.items()):
        actor = int(actor)
        if actor >= len(positions) or actor >= len(inventories) or tuple(target) not in threat_set:
            active.pop(actor, None)
            continue
        inventory = dict(inventories[actor] or {})
        if int(inventory.get("WHEAT", 0) or 0) <= 0:
            active.pop(actor, None)
            continue
        if tuple(positions[actor]) == tuple(target):
            orders[actor] = ["FEED"]
        else:
            orders[actor] = _v17_move_toward(positions[actor], target)

    claimed = {tuple(target) for target in active.values()}
    remaining_actions = max(1, 24 - hour)
    for target in threats:
        if target in claimed:
            continue
        if any(
            tuple(position) == target
            and actor < len(orders)
            and orders[actor]
            and orders[actor][0] == "FEED"
            for actor, position in enumerate(positions)
        ):
            continue
        candidates = []
        for actor, position in enumerate(positions):
            if actor in active or actor >= len(inventories):
                continue
            if int(dict(inventories[actor] or {}).get("WHEAT", 0) or 0) <= 0:
                continue
            distance = abs(int(position[0]) - target[0]) + abs(int(position[1]) - target[1])
            if distance + 1 <= remaining_actions:
                candidates.append((distance, actor))
        if not candidates:
            continue
        distance, actor = min(candidates)
        # Do not seize a worker early; start only at the last safe moment.
        if distance + 1 < remaining_actions:
            continue
        active[actor] = list(target)
        claimed.add(target)
        orders[actor] = ["FEED"] if distance == 0 else _v17_move_toward(positions[actor], target)
    action["farmer"] = orders[0] if orders else ["PASS"]
    action["hands"] = orders[1:]
    return action


def _v17_room_evac(obs, action, step):
    if not _V17_ROOM_GUARD or step < 648:
        return action
    hour = int(_get(obs, "hour", 0) or 0)
    day = int(_get(obs, "day", step // 24) or 0)
    seat = _seat(obs)
    state = _V17_ROOM_EVAC_STATE[seat]
    if step == 0 or step < int(state.get("last_step", -1)) or day != int(state.get("day", -1)):
        state = {"last_step": step, "day": day, "active": None}
        _V17_ROOM_EVAC_STATE[seat] = state
    state["last_step"] = step
    if hour < 21:
        return action
    action = _align_hands(action, obs)
    farm = _farm(obs, seat)
    private = _get(obs, "private", {}) or {}
    positions = [_get(farm, "farmer", [4, 4]), *list(_get(farm, "hands", []) or [])]
    inventories = [dict(value or {}) for value in list(_get(private, "inventories", []) or [])]
    orders = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]
    shed = dict(_get(private, "shed", {}) or {})
    total = sum(max(0, int(value or 0)) for value in shed.values()) + sum(
        max(0, int(value or 0)) for inventory in inventories for value in inventory.values()
    )
    access = _shed_access(len(_get(farm, "tiles", []) or []) or 10)
    if hour == 21 and state.get("active") is None and total > 100:
        candidates = []
        for actor, (position, inventory) in enumerate(zip(positions, inventories)):
            saleable = sum(max(0, int(inventory.get(item, 0) or 0)) for item in _SELLABLE)
            if saleable <= 0 or actor >= len(orders) or (orders[actor] and orders[actor][0] != "PASS"):
                continue
            target = min(access, key=lambda point: abs(int(position[0]) - point[0]) + abs(int(position[1]) - point[1]))
            distance = abs(int(position[0]) - target[0]) + abs(int(position[1]) - target[1])
            if distance <= 2:
                candidates.append((distance, -saleable, actor, target))
        if candidates:
            _, _, actor, target = min(candidates)
            state["active"] = {"actor": actor, "target": list(target)}
    active = state.get("active")
    if active is None:
        return action
    actor = int(active["actor"])
    target = tuple(active["target"])
    if actor >= len(positions) or actor >= len(inventories):
        state["active"] = None
        return action
    if tuple(positions[actor]) != target:
        orders[actor] = _v17_move_toward(positions[actor], target)
    elif hour == 23:
        orders[actor] = ["DROP"]
        market = [list(order) for order in (action.get("market") or [])]
        existing_sales = {}
        for order in market:
            if len(order) >= 3 and order[0] == "SELL":
                existing_sales[order[1]] = existing_sales.get(order[1], 0) + max(0, int(order[2] or 0))
        needed = max(0, total - 100)
        priority = ("WOOL", "MILK", "EGG", "MELON", "STRAWBERRY", "TOMATO", "CARROT", "FERTILIZER", "WHEAT")
        inventory = inventories[actor]
        for item in priority:
            available = max(0, int(inventory.get(item, 0) or 0) - existing_sales.get(item, 0))
            quantity = min(needed, available)
            if quantity <= 0:
                continue
            existing = next(
                (order for order in market if len(order) >= 3 and order[0] == "SELL" and order[1] == item),
                None,
            )
            if existing is not None:
                existing[2] = int(existing[2] or 0) + quantity
            elif len(market) < 10:
                market.append(["SELL", item, quantity])
            else:
                continue
            needed -= quantity
            if needed <= 0:
                break
        action["market"] = market[:10]
    action["farmer"] = orders[0] if orders else ["PASS"]
    action["hands"] = orders[1:]
    return action


def _v17_room_guard(obs, action, step):
    if not _V17_ROOM_GUARD or step % 24 != 23:
        return action
    action = _copy_action(action)
    private = _get(obs, "private", {}) or {}
    shed = {key: max(0, int(value or 0)) for key, value in dict(_get(private, "shed", {}) or {}).items()}
    inventories = [dict(value or {}) for value in list(_get(private, "inventories", []) or [])]
    carried = sum(max(0, int(value or 0)) for inventory in inventories for value in inventory.values())
    farm = _farm(obs, _seat(obs))
    positions = [_get(farm, "farmer", [4, 4]), *list(_get(farm, "hands", []) or [])]
    orders = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]
    produced = consumed = 0
    for actor, order in enumerate(orders):
        if actor >= len(positions) or not isinstance(order, list) or not order:
            continue
        tile = _tile_at(farm, positions[actor])
        if order[0] == "HARVEST" and isinstance(tile, dict):
            produced += max(0, int(tile.get("yield_units", 0) or 0))
        elif order[0] == "COLLECT_FERTILIZER" and isinstance(tile, dict) and tile.get("fertilizer_available", False):
            produced += 1
        elif order[0] in ("FEED", "FERTILIZE"):
            consumed += 1
        elif order[0] == "PLACE" and len(order) >= 2 and order[1] in ("GOOSE", "COW", "SHEEP"):
            consumed += 1
    market = [list(order) for order in (action.get("market") or [])]
    planned_sells = {}
    planned_buys = 0
    for order in market:
        if len(order) < 3:
            continue
        quantity = max(0, int(order[2] or 0))
        if order[0] == "SELL":
            planned_sells[order[1]] = planned_sells.get(order[1], 0) + quantity
        elif order[0] in ("BUY_PRODUCT", "BUY_ANIMAL"):
            planned_buys += quantity
    actual_existing_sells = sum(min(shed.get(item, 0), quantity) for item, quantity in planned_sells.items())
    needed = max(
        0,
        sum(shed.values()) + carried + produced - consumed + planned_buys - actual_existing_sells - 100,
    )
    if needed <= 0:
        return action
    # Finished animal products and sale-only crops are safest to liquidate.
    priority = ("WOOL", "MILK", "EGG", "MELON", "STRAWBERRY", "TOMATO", "CARROT", "FERTILIZER", "WHEAT")
    for item in priority:
        already = planned_sells.get(item, 0)
        available = max(0, shed.get(item, 0) - already)
        quantity = min(needed, available)
        if quantity <= 0:
            continue
        existing = next(
            (order for order in market if len(order) >= 3 and order[0] == "SELL" and order[1] == item),
            None,
        )
        if existing is not None:
            existing[2] = int(existing[2] or 0) + quantity
        elif len(market) < 10:
            market.append(["SELL", item, quantity])
        else:
            continue
        planned_sells[item] = already + quantity
        needed -= quantity
        if needed <= 0:
            break
    action["market"] = market[:10]
    return action

def agent(obs):
    try:
        actions = _kawa_actions(obs)
        step = min(max(0, int(_get(obs, "step", 0) or 0)), len(actions) - 1)
        action = _weed_repair_action(obs, _copy_action(actions[step]), step)
        action = _v17_feed_guard(obs, action, step)
        action = _v17_room_evac(obs, action, step)
        action = _repay_shift(obs, action, step)
        action = _rank_sell_slots(obs, action, None)
        action = _preempt_shift(obs, action, step)
        action = _v17_r5_counter(obs, action, step)
        action = _v17_md_counter(obs, action, step)
        action = _v17_room_guard(obs, action, step)
        action = _terminal_liquidation(obs, action, step)
        return _align_hands(action, obs)
    except Exception:
        farm = _farm(obs, _seat(obs))
        return {
            "farmer": ["PASS"],
            "hands": [["PASS"] for _ in (_get(farm, "hands", []) or [])],
            "market": [],
        }

def _kaggle_submission_entrypoint(obs):
    return agent(obs)

# --- runtime constant overrides ---
_PREEMPT_MAX_BATCH = 30
_PREEMPT_MIN_FUTURE_QUANTITY = 0


# ============ market intervention overlay (pbt/intervene.py) ============
_IV_ENABLED = True
_IV_DUMP_FRAC = 0.8
_IV_LEAD = 3
_IV_SQUEEZE = 0
_IV_REPAY = False          # conserve total volume: repay pulled-forward units
_IV_MIRROR = False        # only act when the boards look near-mirrored
_IV_MIRROR_STEPS = (216, 240, 264)
_IV_MIN_OBS = 3
_IV_PREMIUM = ('MELON', 'MILK', 'STRAWBERRY', 'WOOL', 'FERTILIZER')
_IV_DEBT = {}
_IV_MIRRORED = [None]
_IV_SHOPS = {
    "BAKERY": ("EGG", "WHEAT"), "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"), "YARN_STORE": ("WOOL",),
    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"), "PET_CAFE": ("CARROT",),
    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"),
    "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),
}
_IV_ALL = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK",
           "WOOL", "FERTILIZER")
_IV = {"prev": None, "prev_step": None, "hits": {}, "last": {}, "mine": {}}
_IV_BASE_AGENT = agent


def _iv_town(item, step, shops):
    take = 1 if item != "FERTILIZER" and step % 24 == 0 else 0
    if step % 4 == 0:
        for s in shops:
            pr = _IV_SHOPS.get(s, ())
            if item in pr:
                take += 2 if len(pr) == 1 else 1
    return take


def _iv_observe(inv, step, shops):
    """Opponent sales fall out exactly: inv[t+1] = inv[t] + mine + theirs - town."""
    if _IV["prev"] is not None and _IV["prev_step"] is not None and step > _IV["prev_step"]:
        for item in _IV_ALL:
            delta = int(inv.get(item, 0)) - int(_IV["prev"].get(item, 0))
            taken = sum(_iv_town(item, s, shops)
                        for s in range(_IV["prev_step"], step))
            theirs = delta + taken - int(_IV["mine"].get(item, 0))
            if theirs > 0:
                h = _IV["hits"].setdefault(item, [])
                h.append(step)
                if len(h) > 12:
                    del h[0]
                _IV["last"][item] = step
    _IV["prev"] = dict(inv)
    _IV["prev_step"] = step
    _IV["mine"] = {}


def _iv_signature(farm):
    keys = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON",
            "COW", "SHEEP", "GOOSE", "PASTURE", "COOP", "WEED")
    c = {k: 0 for k in keys}
    for row in (farm.get("tiles") or []):
        for t in row:
            if not isinstance(t, dict):
                continue
            for f in ("crop", "animal", "kind"):
                v = str(t.get(f, "")).upper()
                if v in c:
                    c[v] += 1
                    break
    return (len(farm.get("hands") or []),
            len(farm.get("unlocked_quadrants") or []),
            tuple(c[k] for k in sorted(c)))


def _iv_near_mirror(farms, seat):
    """Same public shape on both boards means production cannot separate the
    game and only sale timing can."""
    if len(farms) < 2:
        return False
    a, b = _iv_signature(farms[seat]), _iv_signature(farms[1 - seat])
    d = abs(a[0] - b[0]) + 3 * abs(a[1] - b[1]) + sum(abs(x - y) for x, y in zip(a[2], b[2]))
    return d <= 6


def _iv_predict(item, step):
    h = _IV["hits"].get(item) or []
    if len(h) < _IV_MIN_OBS:
        return None
    gaps = [b - a for a, b in zip(h, h[1:]) if b > a]
    if not gaps:
        return None
    gaps.sort()
    period = gaps[len(gaps) // 2]
    if period <= 0:
        return None
    return h[-1] + period


def agent(obs):
    action = _IV_BASE_AGENT(obs)
    if not _IV_ENABLED:
        return action
    try:
        o = obs if isinstance(obs, dict) else dict(obs)
        step = int(o.get("step", 0) or 0)
        if not step:
            step = int(o.get("day", 0) or 0) * 24 + int(o.get("hour", 0) or 0)
        if step == 0:
            _IV.update({"prev": None, "prev_step": None, "hits": {}, "last": {}, "mine": {}})
            _IV_DEBT.clear(); _IV_MIRRORED[0] = None
        seat = int(o.get("player", 0) or 0)
        farms = o.get("farms") or []
        market = o.get("market") or {}
        shops = tuple((o.get("town") or {}).get("unlocked_shops") or ())
        _iv_observe(market.get("inventory") or {}, step, shops)
        if seat >= len(farms) or len(farms) < 2:
            return action
        shed = ((o.get("private") or {}).get("shed") or {})
        orders = [list(x) for x in (action.get("market") or [])]
        already = {x[1] for x in orders if x and x[0] == "SELL" and len(x) >= 2}

        if _IV_MIRROR and step in _IV_MIRROR_STEPS:
            _IV_MIRRORED[0] = _iv_near_mirror(farms, seat)
        gate_ok = (not _IV_MIRROR) or bool(_IV_MIRRORED[0])

        # Repay first: units pulled forward are subtracted from the tape's own
        # later SELL of the same item, so the two-turn total is conserved and we
        # never sell stock twice.
        if _IV_REPAY and _IV_DEBT:
            newo = []
            for x in orders:
                if x and x[0] == "SELL" and len(x) >= 3 and _IV_DEBT.get(x[1], 0) > 0:
                    q = int(x[2]); cut = min(q, _IV_DEBT[x[1]])
                    _IV_DEBT[x[1]] -= cut; q -= cut
                    if q <= 0:
                        continue
                    x = [x[0], x[1], q]
                newo.append(x)
            orders = newo
            already = {x[1] for x in orders if x and x[0] == "SELL" and len(x) >= 2}

        # dump ahead of their predicted sale
        for item in (_IV_PREMIUM if gate_ok else ()):
            if len(orders) >= 10 or item in already:
                continue
            nxt = _iv_predict(item, step)
            if nxt is None or not (step < nxt <= step + _IV_LEAD):
                continue
            have = int(shed.get(item, 0) or 0)
            qty = int(have * _IV_DUMP_FRAC)
            if qty > 0:
                orders.append(["SELL", item, qty])
                if _IV_REPAY:
                    _IV_DEBT[item] = _IV_DEBT.get(item, 0) + qty

        # squeeze feed price against an animal-heavy opponent
        if _IV_SQUEEZE and len(orders) < 10:
            opp = farms[1 - seat]
            animals = sum(1 for row in (opp.get("tiles") or []) for t in row
                          if isinstance(t, dict) and "animal" in t)
            if animals >= _IV_SQUEEZE:
                money = float(farms[seat].get("money", 0) or 0)
                px = max(1, int((market.get("prices") or {}).get("WHEAT", 25)))
                room = 100 - sum(shed.values())
                n = int(min(animals, room, max(0, (money - 500) // px)))
                if n > 0 and not any(x[0] == "BUY_PRODUCT" and x[1] == "WHEAT"
                                     for x in orders if x):
                    orders.append(["BUY_PRODUCT", "WHEAT", n])
        action["market"] = orders[:10]
        for x in action["market"]:
            if x and x[0] == "SELL" and len(x) >= 3:
                _IV["mine"][x[1]] = _IV["mine"].get(x[1], 0) + int(x[2])
    except Exception:
        return action
    return action


def _submission_entry(obs):
    return agent(obs)





# =========== route table as a flat array (pbt/flatroute.py) ===========
# The tape, addressed. State s1 = (legacy * 5 + label) * 719 + step, one int in
# [0, 7190). `_FR_CODES[i]` is another such int and decodes as
# `divmod(code, 719) -> (table, step)`, so identity is `_FR_CODES[i] == i` and
# the ten arrays above are still the only place actions live.
#
#     _FR_REMAP[i] = j      state i plays state j's action   (edit a code)
#     _FR_EDITS[i] = act    state i plays this literal action (edit an action)
#
# `_kawa_actions` returns a proxy rather than a list so that all THREE readers
# of the table -- the base lookup, `_trace_actor_action` (current step, weed
# replay) and `_future_sells` (step + 1, pre-empt borrow) -- go through the same
# array. An edit is therefore coherent at every site by construction.
#
# With both dicts empty this file is the base agent exactly, to the dollar.
# Equivalence is a property of a BUILD, not of the generator: re-run
# `dynamic/tape/v3_bench.py` and `dynamic/tape/v3_submit_check.py` after
# regenerating rather than trusting a number in a comment.

_FR_LABELS = ['10c4s_3q', '8c6s_3q', '6c8s_3q', '6c12s_4q_first_yarn', '6c12s_4q_second_yarn']
_FR_LABEL_CODE = {_n: _i for _i, _n in enumerate(_FR_LABELS)}
_FR_NLABEL = len(_FR_LABELS)
_FR_STEPS = 719
_FR_N = 2 * _FR_NLABEL * _FR_STEPS
_FR_TABLES = [_ACTIONS_10C4S_3Q, _ACTIONS_8C6S_3Q, _ACTIONS_6C8S_3Q, _ACTIONS_6C12S_4Q_FIRST_YARN, _ACTIONS_6C12S_4Q_SECOND_YARN, _LEGACY_ACTIONS_10C4S_3Q, _LEGACY_ACTIONS_8C6S_3Q, _LEGACY_ACTIONS_6C8S_3Q, _LEGACY_ACTIONS_6C12S_4Q_FIRST_YARN, _LEGACY_ACTIONS_6C12S_4Q_SECOND_YARN]

_FR_REMAP = {}          # sparse: state index -> state index whose action to play
_FR_EDITS = {}          # sparse: state index -> literal action dict

# A real list, so search tooling can mutate it in place and numpy can wrap it.
_FR_CODES = list(range(_FR_N))
for _k, _v in _FR_REMAP.items():
    _FR_CODES[_k] = _v


def _fr_key(legacy, label, step):
    """(legacy, label, step) -> s1. The one place the layout is defined."""
    return (legacy * _FR_NLABEL + _FR_LABEL_CODE[label]) * _FR_STEPS + step


def _fr_lookup(legacy, label, step):
    step = min(max(0, int(step)), _FR_STEPS - 1)
    i = _fr_key(legacy, label, step)
    act = _FR_EDITS.get(i)
    if act is not None:
        return act
    t, s = divmod(_FR_CODES[i], _FR_STEPS)
    return _FR_TABLES[t][s]


class _FrRoute(object):
    """Indexes like the array it replaces. len() and [int] are the only uses."""

    __slots__ = ("_legacy", "_label")

    def __init__(self, legacy, label):
        self._legacy, self._label = legacy, label

    def __len__(self):
        return _FR_STEPS

    def __getitem__(self, step):
        return _fr_lookup(self._legacy, self._label, step)


_FR_ROUTES = {(_lg, _lb): _FrRoute(_lg, _lb)
              for _lg in (0, 1) for _lb in _FR_LABELS}


def _kawa_actions(obs):
    # Same two calls in the same order as the original (source 135-136).
    # `_kawa_use_legacy_layout` latches per seat and must run once per call, and
    # `_kawa_route_label` is resolved at call time so a tape-selection override
    # appended after this block still wins.
    label = _kawa_route_label(obs)
    legacy = 1 if _kawa_use_legacy_layout(obs) else 0
    return _FR_ROUTES[(legacy, label)]


def _flatroute_entry(obs):
    return agent(obs)
